const indexes: Record<Exclude<Language, 'tr'>, number> = { en: 0, de: 1, fr: 2, ru: 3, pl: 4 }

export function translate(language: Language, source: string, values?: Record<string, string | number>): string {
  const template = language === 'tr' ? source : dictionary[source]?.[indexes[language]] ?? source
  return template.replace(/\{(\w+)\}/g, (match, key: string) => values?.[key]?.toString() ?? match)
}
